import sys

data = sys.stdin.read().split()
s = data[0]
st = []
pairs = {")": "(", "]": "[", "}": "{"}
ok = True
for ch in s:
    if ch in "([{":
        st.append(ch)
    else:
        if not st or st.pop() != pairs[ch]:
            ok = False
            break
print("YES" if ok and not st else "NO")

